#[cfg(windows)]
fn get_compiler_version_msvc(m: i32, mf: i32) -> i32 {
    if m == mf / 10000 {
        return DOCTEST_COMPILER(m / 100, m % 100, mf % 10000);
    } else {
        return DOCTEST_COMPILER(m / 100, (mf / 100000) % 100, mf % 100000);
    }
    fn DOCTEST_COMPILER(major: i32, minor: i32, patch: i32) -> i32 {
        major * 10000000 + minor * 100000 + patch
    }
}

fn get_compiler_version_gcc_or_clang(
    major: Option<i32>,
    minor: Option<i32>,
    patch: Option<i32>,
    intel: Option<i32>,
) -> i32 {
    if (cfg!(target_os = "linux") || cfg!(target_os = "macos")) && intel.is_none() {
        if major.is_some() && minor.is_some() && patch.is_some() {
            return DOCTEST_COMPILER(major.unwrap(), minor.unwrap(), patch.unwrap());
        } else {
            return 0;
        }
    } else {
        return 0;
    }
    fn DOCTEST_COMPILER(major: i32, minor: i32, patch: i32) -> i32 {
        major * 10000000 + minor * 100000 + patch
    }
}

