fn doctest_clang_version() -> i32 {
    get_compiler_version_gcc_or_clang(
        option_env!("clang_major").and_then(|v| v.parse().ok()),
        option_env!("clang_minor").and_then(|v| v.parse().ok()),
        option_env!("clang_patchlevel").and_then(|v| v.parse().ok()),
        None,
    )
}

