macro_rules! DOCTEST_DEFINE_DECORATOR {
    ($name:ident, $type:ty, $def:expr) => {
        struct $name {
            data: $type,
        }

        impl $name {
            fn fill(&self, _: &mut TestCase) {
                let _ = self.data;
            }

            fn new(data: $type) -> Self {
                Self { data }
            }
        }

        impl Default for $name {
            fn default() -> Self {
                $name { data: $def }
            }
        }
    };
}

